#!/bin/sh
# Generated by FWShift: the rule tables of one Cisco Meraki MX network, put through the Dashboard API (v1).
# Read the report first: what is not written is listed there. Each put replaces the whole table.
# Usage: MERAKI_API_KEY=... NETWORK_ID=N_... [MERAKI_BASE=https://api.meraki.com/api/v1] [DRY_RUN=1] sh this-file
# DRY_RUN=1 only writes the bodies, and needs no key. The backups (before-*.json) end in the fixed default rule of the
# MX: to put a backup back, remove that last rule (comment "Default rule") from its rules first.
set -eu
OUT="${OUT:-meraki-$(date +%Y%m%d%H%M%S)}"
mkdir -p "$OUT"
api() {  # api METHOD PATH [BODY-FILE]
  tries=0
  while :; do
    if [ -n "${3:-}" ]; then
      code=$(curl -sS -o "$OUT/last.json" -D "$OUT/last.hdr" -w '%{http_code}' -X "$1" -H "Authorization: Bearer $MERAKI_API_KEY" \
             -H 'Content-Type: application/json' -H 'Accept: application/json' --data-binary @"$3" "$MERAKI_BASE$2")
    else
      code=$(curl -sS -o "$OUT/last.json" -D "$OUT/last.hdr" -w '%{http_code}' -X "$1" -H "Authorization: Bearer $MERAKI_API_KEY" \
             -H 'Accept: application/json' "$MERAKI_BASE$2")
    fi
    case "$code" in
      2??) cat "$OUT/last.json"; return 0 ;;
      429) tries=$((tries+1)); [ "$tries" -le 5 ] || { echo "rate limited: $2" >&2; return 1; }
           wait=$(sed -n 's/^[Rr]etry-[Aa]fter: *\([0-9]*\).*/\1/p' "$OUT/last.hdr"); sleep "${wait:-2}" ;;
      *) echo "HTTP $code on $1 $2:" >&2; cat "$OUT/last.json" >&2; return 1 ;;
    esac
  done
}
cat > "$OUT/l3FirewallRules.json" <<'FWSHIFT_EOF'
{
 "rules": [
  {
   "comment": "pre-spoofed",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "10.0.0.0/8",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": true
  },
  {
   "comment": "No production cell talks to the Internet",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "10.30.0.0/24",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": true
  },
  {
   "comment": "Uncategorised web",
   "policy": "deny",
   "protocol": "tcp",
   "srcPort": "Any",
   "srcCidr": "10.10.0.200/29,10.10.0.208/28,10.10.0.224/28,10.10.0.240/29,10.10.0.248/31,10.10.0.250/32",
   "destPort": "80",
   "destCidr": "Any",
   "syslogEnabled": true
  },
  {
   "comment": "Uncategorised web",
   "policy": "deny",
   "protocol": "tcp",
   "srcPort": "Any",
   "srcCidr": "10.10.0.200/29,10.10.0.208/28,10.10.0.224/28,10.10.0.240/29,10.10.0.248/31,10.10.0.250/32",
   "destPort": "443",
   "destCidr": "Any",
   "syslogEnabled": true
  },
  {
   "comment": "Reset the rest from inside",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "Any",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": true
  },
  {
   "comment": "the source blocks what no rule matches",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "Any",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": false
  }
 ],
 "syslogDefaultRule": false
}
FWSHIFT_EOF
if [ "${DRY_RUN:-0}" = 1 ]; then echo "DRY_RUN: the bodies are in $OUT"; exit 0; fi
: "${MERAKI_API_KEY:?set MERAKI_API_KEY}"
: "${NETWORK_ID:?set NETWORK_ID}"
MERAKI_BASE="${MERAKI_BASE:-https://api.meraki.com/api/v1}"
api GET "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" > "$OUT/before-l3FirewallRules.json"
api PUT "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" "$OUT/l3FirewallRules.json" > "$OUT/after-l3FirewallRules.json"
sleep 0.2
echo "done; the tables as they were are in $OUT/before-*.json"
# Not written:
#   pre-backup: the source of the rule is in zone inside, and the MX names no zone: give the networks behind inside with --zone-network; the destination of the rule is in zone dmz, and the MX names no zone: give the networks behind dmz with --zone-network
#   pre-partner-gre: the source of the rule is in zone outside, and the MX names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and the MX names no zone: give the networks behind dmz with --zone-network; an ICMP type, or a protocol other than TCP, UDP, ICMP and
#   pre-partner-gre-reverse: the source of the rule is in zone dmz, and the MX names no zone: give the networks behind dmz with --zone-network; the destination of the rule is in zone outside, and the MX names no zone: give the networks behind outside with --zone-network; an ICMP type, or a protocol other than TCP, UDP, ICMP and
#   prefilter-default-block-tunnels: an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
#   LAN web: the source of the rule is in zone inside, and the MX names no zone: give the networks behind inside with --zone-network; the destination of the rule is in zone outside, and the MX names no zone: give the networks behind outside with --zone-network
#   LAN DNS and NTP: the source of the rule is in zone inside, and the MX names no zone: give the networks behind inside with --zone-network; the destination of the rule is in zone outside, and the MX names no zone: give the networks behind outside with --zone-network
#   Updates: the source of the rule is in zone inside, dmz, and the MX names no zone: give the networks behind inside, dmz with --zone-network; the destination of the rule is in zone outside, and the MX names no zone: give the networks behind outside with --zone-network
#   Inbound web: the source of the rule is in zone outside, and the MX names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and the MX names no zone: give the networks behind dmz with --zone-network
#   Inbound mail: the source of the rule is in zone outside, and the MX names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and the MX names no zone: give the networks behind dmz with --zone-network
#   Admin access: the source of the rule is in zone inside, and the MX names no zone: give the networks behind inside with --zone-network; the destination of the rule is in zone dmz, and the MX names no zone: give the networks behind dmz with --zone-network; an ICMP type, or a protocol other than TCP, UDP, ICMP and I
#   Helpdesk RDP: source user match CORP\helpdesk is not converted; the source of the rule is in zone inside, and the MX names no zone: give the networks behind inside with --zone-network; the destination of the rule is in zone dmz, and the MX names no zone: give the networks behind dmz with --zone-network
#   Staff social media: not converted: an application condition
#   Partner service: the source of the rule is in zone outside, and the MX names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and the MX names no zone: give the networks behind dmz with --zone-network; an ICMP type, or a protocol other than TCP, UDP, ICMP and
#   DNS answers to resolver: the source of the rule is in zone outside, and the MX names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and the MX names no zone: give the networks behind dmz with --zone-network
#   Branch IPv6: the source of the rule is in zone outside, and the MX names no zone: give the networks behind outside with --zone-network; the destination of the rule is in zone dmz, and the MX names no zone: give the networks behind dmz with --zone-network; an ICMP type, or a protocol other than TCP, UDP, ICMP and
#   Ping out: the source of the rule is in zone inside, dmz, and the MX names no zone: give the networks behind inside, dmz with --zone-network; an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
